-- H2 版：对应 MySQL 的 V1__workspace.sql。改动：parameters/metrics/fields_json/rows_json/warnings_json/config_json 6 个 JSON 列改用 CLOB（H2 的 JSON 类型会给字符串参数多包一层引号，代码以字符串读写，CLOB 语义一致）；experiments/charts 的 updated_at 去掉 ON UPDATE CURRENT_TIMESTAMP(3)（由代码在 UPDATE 语句里显式赋值，见 14-1-3）。AUTO_INCREMENT、TIMESTAMP(3) 默认值、LONGBLOB、外键实测 H2 2.3.232（MODE=MySQL）支持，原样保留。
CREATE TABLE projects (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE experiments (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, parameters CLOB NOT NULL, metrics CLOB NOT NULL, notes TEXT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE datasets (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE dataset_versions (id BIGINT PRIMARY KEY AUTO_INCREMENT, dataset_id BIGINT NOT NULL, version INT NOT NULL, filename VARCHAR(255) NOT NULL, sha256 CHAR(64) NOT NULL, original_file LONGBLOB NOT NULL, fields_json CLOB NOT NULL, rows_json CLOB NOT NULL, warnings_json CLOB NOT NULL, row_count INT NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(dataset_id,version), FOREIGN KEY(dataset_id) REFERENCES datasets(id));
CREATE TABLE charts (id BIGINT PRIMARY KEY AUTO_INCREMENT, project_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, revision INT NOT NULL DEFAULT 0, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE chart_versions (id BIGINT PRIMARY KEY AUTO_INCREMENT, chart_id BIGINT NOT NULL, dataset_version_id BIGINT NOT NULL, version INT NOT NULL, schema_version INT NOT NULL, config_json CLOB NOT NULL, created_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE(chart_id,version), FOREIGN KEY(chart_id) REFERENCES charts(id), FOREIGN KEY(dataset_version_id) REFERENCES dataset_versions(id));
